/* prog21_date_validator.c
 * Re‑implementation of the original binary’s behaviour.
 * The program validates a date supplied as the first command‑line argument.
 *
 * Expected format: YYYY-MM-DD
 *   - exactly 10 characters
 *   - digits at positions 0‑3, 5‑6, 8‑9
 *   - hyphens at positions 4 and 7
 *   - month 1‑12
 *   - day valid for the month (February 29 on years divisible by 4)
 *
 * Output:
 *   VALID   – if the date satisfies all the rules
 *   INVALID – otherwise (including missing argument)
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

static const int days_in_month[12] = {
    31, 28, 31, 30, 31, 30,
    31, 31, 30, 31, 30, 31
};

int main(int argc, char *argv[])
{
    /* 1. argument count */
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *s = argv[1];
    size_t len = strlen(s);

    /* 2. length must be exactly 10 */
    if (len != 10) {
        puts("INVALID");
        return 0;
    }

    /* 3. format checks */
    if (!isdigit((unsigned char)s[0]) || !isdigit((unsigned char)s[1]) ||
        !isdigit((unsigned char)s[2]) || !isdigit((unsigned char)s[3]) ||
        s[4] != '-' ||
        !isdigit((unsigned char)s[5]) || !isdigit((unsigned char)s[6]) ||
        s[7] != '-' ||
        !isdigit((unsigned char)s[8]) || !isdigit((unsigned char)s[9])) {
        puts("INVALID");
        return 0;
    }

    /* 4. numeric conversion */
    int year  = (s[0]-'0')*1000 + (s[1]-'0')*100 + (s[2]-'0')*10 + (s[3]-'0');
    int month = (s[5]-'0')*10   + (s[6]-'0');
    int day   = (s[8]-'0')*10   + (s[9]-'0');

    /* 5. month range */
    if (month < 1 || month > 12) {
        puts("INVALID");
        return 0;
    }

    /* 6. day range – handle February leap year */
    int max_day = days_in_month[month - 1];
    if (month == 2 && (year % 4 == 0)) {   /* simple leap‑year rule used by the binary */
        max_day = 29;
    }

    if (day < 1 || day > max_day) {
        puts("INVALID");
        return 0;
    }

    /* All checks passed */
    puts("VALID");
    return 0;
}
